import { describe, expect, it } from 'vitest'
import { parseGrammar } from './grammar'
import { quote } from './symbols'

// Every string of length 1..3 over an alphabet that covers the syntax characters.
const ALPHABET = ['a', 'E', "'", '"', ' ', '#', '|', '-', '>', 'ε', '→', ':', '=']
function* strings(max: number): Generator<string> {
  let level = ['']
  for (let n = 1; n <= max; n++) {
    level = level.flatMap((s) => ALPHABET.map((c) => s + c))
    yield* level
  }
}

const rules = (text: string) => parseGrammar(text).rules.map((r) => [r.lhs, r.rhs])

describe('parseGrammar', () => {
  it('reads rules, alternatives, continuation lines, ε and comments', () => {
    const text = "E -> T E'  # súčet\nE' -> + T E' | ε\n   | eps\nF→( E )\nG::=\n"
    expect(rules(text)).toEqual([
      ['E', ['T', "E'"]],
      ["E'", ['+', 'T', "E'"]],
      ["E'", []],
      ["E'", []],
      ['F', ['(', 'E', ')']],
      ['G', []],
    ])
    expect(parseGrammar(text).errors).toEqual([])
  })

  it('accepts an arrow without spaces around it', () => {
    expect(rules("E->T E'")).toEqual([['E', ['T', "E'"]]])
  })

  it('reads a quoted left-hand side as the symbol inside the quotes', () => {
    expect(rules(`"E'" -> x\n'|' -> y`)).toEqual([
      ["E'", ['x']],
      ['|', ['y']],
    ])
  })

  it('reports a line without an arrow', () => {
    expect(parseGrammar('E T').errors).toEqual(['Riadok 1: chýba „->“ (E T)'])
  })

  it('reports a left-hand side that is not a single symbol', () => {
    expect(parseGrammar('A B -> x').errors).toHaveLength(1)
    expect(parseGrammar('A B -> x').rules).toEqual([])
  })

  it('reads any quoted symbol back as itself on both sides of a rule', () => {
    const named = ['ε', 'eps', 'epsilon', '::=', "it's", 'a#b']
    const failures = [...named, ...strings(3)]
      .filter((s) => !(s.includes("'") && s.includes('"')))
      .filter((s) => JSON.stringify(rules(`${quote(s)} -> ${quote(s)} | ${quote(s)}`)) !== JSON.stringify([[s, [s]], [s, [s]]]))
    expect(failures).toEqual([])
  })
})
